#!/usr/bin/env sh
# fetch OSETH (Transport Authority of Thessaloniki S.A.) (GR) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://data.gov.gr/dataset/42c9a7da-c86c-48b1-914c-f340e8bef00d/resource/4ad67d72-d443-4969-97fc-6c1ada64b87a/download/20260812_gtfs.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
